<script setup lang="ts">
import { computed, inject, nextTick, onMounted, onUnmounted, ref } from 'vue'
import TypoText from './TypoText.vue'
import content from '../../content/cases/dc-vendor-app-ux.json'
import { useHeroMotion } from './hero-motion'
import { vMediaReady } from './media-readiness'
import { vLayeredScene } from './layered-scene-readiness'
import LayeredSceneFallback from './LayeredSceneFallback.vue'
import { createHeroDraft, getHeroBreakpoint, heroBreakpoints, heroReferences, heroSceneEditorKey, type HeroBreakpoint } from './dc-vendor-app-ux-hero.scene-context'
import { heroAssets } from './dc-vendor-app-ux-hero.assets'

const props=defineProps<{breakpoint?:HeroBreakpoint}>()
const root=ref<HTMLElement>(),viewport=ref(320),width=ref(320),ready=ref(false)
const editor=inject(heroSceneEditorKey,undefined),defaults=createHeroDraft()
const breakpoint=computed(()=>props.breakpoint??getHeroBreakpoint(viewport.value))
const layers=computed(()=>(editor?.draft??defaults)[breakpoint.value])
const reference=computed(()=>heroReferences[breakpoint.value])
const nodes:HTMLElement[]=[]
let offsets:number[]=[]
function render(values=offsets){offsets=values;nodes.forEach((node,i)=>node?.style.setProperty('--parallax-x',(values[i]??0)+'px'))}
const {resetMotion,replayIntro,maybeIntro,pointerDown}=useHeroMotion({root,layers:()=>layers.value,breakpoint:()=>breakpoint.value,mode:()=>editor?.mode.value??'Interaction',width:()=>width.value,viewport:()=>viewport.value,render,scope:'viewport'})
const profiles=[...heroBreakpoints].reverse()
function asset(profile:HeroBreakpoint,index:number){const file=heroAssets[profile][index]?.file;return file?'/cases/dc-vendor-app-ux/hero-layers/'+file:undefined}
function media(profile:HeroBreakpoint){return '(min-width: '+(profile==='base'?0:Number(profile.slice(4)))+'px)'}
function profileValues(profile:HeroBreakpoint){
 const r=heroReferences[profile],scene=defaults[profile],values:Record<string,string>={aspect:r.width+' / '+r.height,background:r.width<1024?'var(--surface-default)':'transparent'}
 const length=(n:number)=>n/r.width*100+'cqw'
 for(let i=0;i<11;i++){
 const l=scene[i],a=heroAssets[profile][i]
 const fields={x:l&&a?l.x+a.x:0,y:l&&a?l.y+a.y:0,w:a?.width??0,h:a?.height??0,blur:a?.blur??0,backdrop:a?.backdrop??0,radius:a?.radius??0}
 for(const [key,value]of Object.entries(fields))values[key+i]=length(value)
 values['opacity'+i]=String(a?.opacity??0)
 }
 return values
}
const rootStyle=computed(()=>{
 const values:Record<string,string>={}
 for(const bp of heroBreakpoints)for(const [key,value]of Object.entries(profileValues(bp)))values['--'+bp+'-'+key]=value
 if(props.breakpoint)for(const [key,value]of Object.entries(profileValues(props.breakpoint)))values['--initial-'+key]=value
 if(ready.value){values.aspectRatio=reference.value.width+' / '+reference.value.height;values['--current-background']=reference.value.width<1024?'var(--surface-default)':'transparent'}
 return values
})
function geometry(index:number){
 if(!ready.value)return
 const l=layers.value[index]!,a=heroAssets[breakpoint.value][index]!,length=(n:number)=>n/reference.value.width*100+'cqw'
 return {left:length(l.x+a.x),top:length(l.y+a.y),width:length(a.width),height:length(a.height),filter:a.blur?'blur('+length(a.blur)+')':'none','--backdrop':length(a.backdrop),'--radius':length(a.radius),'--opacity':a.opacity}
}
function paintStyle(index:number){
 const crop=heroAssets[breakpoint.value][index]?.crop
 return crop?{position:'absolute' as const,left:crop.left+'%',top:crop.top+'%',width:crop.width+'%',height:crop.height+'%',objectFit:'fill' as const}:undefined
}
function sync(){viewport.value=window.innerWidth;width.value=root.value?.getBoundingClientRect().width||viewport.value;void nextTick(()=>render())}
let observer:ResizeObserver|undefined
onMounted(()=>{sync();ready.value=true;observer=new ResizeObserver(sync);observer.observe(root.value!);window.addEventListener('resize',sync)})
onUnmounted(()=>{observer?.disconnect();window.removeEventListener('resize',sync)})
defineExpose({resetMotion,replayIntro})
</script>

<template>
 <section v-media-ready v-layered-scene ref="root" class="dc-vendor-app-ux-hero media-skeleton" :data-breakpoint="breakpoint" :data-ready="ready" :style="rootStyle" :aria-label="content.hero.title" @scene-ready="maybeIntro" @pointerdown="pointerDown">
  <LayeredSceneFallback name="dc-vendor-app-ux-hero" />
  <div class="dc-vendor-app-ux-hero__art" aria-hidden="true">
   <div v-for="(layer,index) in layers" v-media-ready :key="layer.name" :ref="el=>{if(el)nodes[index]=el as HTMLElement}" class="dc-vendor-app-ux-hero__layer" :class="'dc-ux-layer-'+index" :data-layer="layer.name" :data-animation-enabled="layer.animationEnabled" :style="geometry(index)">
    <div v-if="layer.name==='Title-shadow'" class="dc-vendor-app-ux-hero__shadow" />
    <picture v-else class="dc-vendor-app-ux-hero__media" :class="{'dc-vendor-app-ux-hero__media--title':index===layers.length-1}">
     <template v-if="!props.breakpoint"><source v-for="profile in profiles" :key="profile" :media="media(profile)" :srcset="asset(profile,index)" /></template>
     <img :src="asset(breakpoint,index)" :fetchpriority="index === layers.length - 1 ? 'high' : 'auto'" alt="" draggable="false" decoding="async" :style="paintStyle(index)" @load="maybeIntro" />
    </picture>
   </div>
  </div>
  <div class="dc-vendor-app-ux-hero__semantic"><TypoText tag="h1" :content="content.hero.title" /><TypoText tag="p" :content="content.hero.subtitle" /><TypoText tag="p" :content="content.hero.tagline" /></div>
 </section>
</template>

